import hashlib, json, tempfile, unittest
from pathlib import Path
from unittest import mock
import queue as Q
PACKET=b"hello\n"; SHA=hashlib.sha256(PACKET).hexdigest()
class Fake:
    rcs={}; sts={}; made=[]
    def __init__(self,cmd,**kw):
        self.task=cmd[cmd.index("--task-id")+1]; out=Path(cmd[cmd.index("--out")+1])
