        self.t=tempfile.TemporaryDirectory(); self.addCleanup(self.t.cleanup)
        self.p=Path(self.t.name)/"p"; self.p.mkdir(); (self.p/"packet.txt").write_bytes(PACKET)
        self.s=Path(self.t.name)/"s"; self.r=Path(self.t.name)/"runner.py"; self.r.write_text("")
    def job(self,tid,after=None,priority=0,run_id=None,**kw):
        j={"task_id":tid,"run_id":run_id or tid,"packet":"packet.txt","packet_sha256":SHA,"model":"deepseek-v4.1-flash","domain":"d","task_type":"t","difficulty":"low","acceptance_criteria":"a","priority":priority,"after":after or []}
        j.update(kw); return j
    def q(self,jobs,max_active=4): return {"schema":1,"max_active":max_active,"jobs":jobs}
