        Fake.rcs=rcs or {}; Fake.sts=sts or {}; Fake.made=[]
        with mock.patch.object(Q.subprocess,"Popen",Fake), mock.patch.object(Q,"read_start_ticks",return_value=7), mock.patch.object(Q.time,"sleep"):
            return Q.run_session(q,self.p,self.s,self.r)
    def write(self,q):
        st=Q.new_state(q); Q.save_state(self.s,st); return st
class Tests(Base):
    def test_validation(self):
        def e(jobs): return Q.validate_queue(self.q(jobs),self.p)
        self.assertTrue(any("duplicate" in x for x in e([self.job("a"),self.job("a",run_id="b")])))
        self.assertTrue(any("cycle" in x for x in e([self.job("a",[{"task_id":"b","condition":"on_success"}]),self.job("b",[{"task_id":"a","condition":"on_terminal"}])])))
        self.assertTrue(any("traversal" in x for x in e([self.job("a",packet="../x.txt")])))
