        st["jobs"]["a"].update({"status":"RUNNING","claim":{"pid":123,"start_ticks":9}}); st["jobs"]["b"].pop("status",None); Q.save_state(self.s,st)
        with mock.patch.object(Q,"pid_alive",return_value=False), mock.patch.object(Q.subprocess,"Popen") as pop, mock.patch.object(Q.time,"sleep"):
            summary=Q.run_session(q,self.p,self.s,self.r)
        self.assertFalse(pop.called); st=Q.load_state(self.s)
        self.assertEqual(st["jobs"]["a"]["status"],"NEEDS_REVIEW"); self.assertEqual(st["jobs"]["b"]["status"],"NEEDS_REVIEW"); self.assertEqual(summary["exit_code"],1)
    def test_dependency_and_nonzero(self):
