        self.assertEqual(st["jobs"]["a"]["status"],"FAILED"); self.assertEqual(st["jobs"]["b"]["status"],"BLOCKED_DEPENDENCY"); self.assertEqual(st["jobs"]["c"]["status"],Q.SUCCESS); self.assertEqual(summary["exit_code"],1)
    def test_success_and_log(self):
        summary=self.run(self.q([self.job("a")])); st=Q.load_state(self.s)
        self.assertEqual(st["jobs"]["a"]["status"],Q.SUCCESS); self.assertEqual(summary["exit_code"],0); self.assertTrue((self.s/"runs"/"a"/"runner.log").exists())
    def test_log_and_popen_failures_are_local(self):
