    def test_invalid_runner_status(self):
        summary=self.run(self.q([self.job("a")]),sts={"a":"WRITE_IN_PROGRESS"}); st=Q.load_state(self.s)
        self.assertEqual(st["jobs"]["a"]["status"],"NEEDS_REVIEW"); self.assertEqual(summary["exit_code"],1)
